export type PlatformResponse<T> = { data: T; requestId: string | null; traceparent: string | null; auditMessageId: string | null; routePolicyRevision: string | null; location: string | null };

export class PlatformApiError extends Error {
  readonly problem: ProblemDetails;
  constructor(problem: ProblemDetails) { super(problem.detail); this.name = 'PlatformApiError'; this.problem = problem; }
}

export type PlatformGatewayClient = ReturnType<typeof createPlatformGatewayClient>;

export function createPlatformGatewayClient(baseUrl = '') {
  const request = async <T>(path: string, schema: z.ZodType<T>, init?: RequestInit): Promise<PlatformResponse<T>> => {
    const headers = new Headers(init?.headers);
    if (!headers.has('Accept')) headers.set('Accept', 'application/json, application/problem+json');
    const response = await fetch(`${baseUrl}${path}`, { ...init, headers, credentials: 'same-origin' });
    if (response.status === 204) return { data: undefined as T, requestId: response.headers.get('x-request-id'), traceparent: response.headers.get('traceparent'), auditMessageId: response.headers.get('x-audit-message-id'), routePolicyRevision: response.headers.get('x-route-policy-revision'), location: response.headers.get('location') };
    const payload: unknown = await response.json();
    if (!response.ok) throw new PlatformApiError(problemDetailsSchema.parse(payload));
    return { data: schema.parse(payload), requestId: response.headers.get('x-request-id'), traceparent: response.headers.get('traceparent'), auditMessageId: response.headers.get('x-audit-message-id'), routePolicyRevision: response.headers.get('x-route-policy-revision'), location: response.headers.get('location') };
  };

  const listPath = (path: string, params: RegistryListParams = {}) => {
    const query = new URLSearchParams();
    if (params.limit !== undefined) query.set('limit', String(params.limit));
    if (params.cursor) query.set('cursor', params.cursor);
    return `${path}${query.size ? `?${query.toString()}` : ''}`;
  };

  const mutation = <I, O>(
    path: string,
    method: 'POST' | 'PATCH',
    body: I,
    inputSchema: z.ZodType<I>,
    outputSchema: z.ZodType<O>,
    init?: RequestInit,
  ) => {
    const headers = new Headers(init?.headers);
    headers.set('Content-Type', 'application/json');
    return request(path, outputSchema, {
      ...init,
      method,
      headers,
      body: JSON.stringify(inputSchema.parse(body)),
    });
  };

  return {
    getHealth: (params: { includeBuild?: boolean } = {}, init?: RequestInit) => {
      const query = new URLSearchParams();
      if (params.includeBuild !== undefined) query.set('includeBuild', String(params.includeBuild));
      const suffix = query.size ? `?${query.toString()}` : '';
      return request(`/api/v1/health${suffix}`, healthResponseSchema, { ...init, method: 'GET' });
    },
    getVersion: (init?: RequestInit) => request('/api/v1/version', buildInfoSchema, { ...init, method: 'GET' }),
    getPlatformStatus: (init?: RequestInit) => request('/api/v1/platform/status', platformStatusResponseSchema, { ...init, method: 'GET' }),
    getCurrentPrincipal: (init?: RequestInit) => request('/api/v1/principal', currentPrincipalResponseSchema, { ...init, method: 'GET' }),
    loginUrl: (params: { returnTo?: string; loginHint?: string; assurance?: 'normal' | 'high' } = {}) => {
      const query = new URLSearchParams();
      if (params.returnTo) query.set('returnTo', params.returnTo);
      if (params.loginHint) query.set('login_hint', params.loginHint);
      if (params.assurance) query.set('assurance', params.assurance);
      return `/api/v1/auth/login${query.size ? `?${query.toString()}` : ''}`;
    },
    logout: (csrfToken: string, init?: RequestInit) => request('/api/v1/auth/logout', z.undefined(), {
      ...init, method: 'POST', headers: { ...Object.fromEntries(new Headers(init?.headers)), 'X-CSRF-Token': csrfToken },
    }),
    revokeSession: (sessionId: string, csrfToken: string, init?: RequestInit) => request(
      '/api/v1/auth/sessions/{sessionId}/revoke'.replace('{sessionId}', encodeURIComponent(sessionId)),
      sessionRevocationResponseSchema,
      { ...init, method: 'POST', headers: { ...Object.fromEntries(new Headers(init?.headers)), 'X-CSRF-Token': csrfToken } },
    ),
    getSessionAuditEvent: (messageId: string, init?: RequestInit) => request(
      '/api/v1/audit/session-events/{messageId}'.replace('{messageId}', encodeURIComponent(messageId)),
      auditRecordSchema,
      { ...init, method: 'GET' },
    ),
    listSites: (params: RegistryListParams = {}, init?: RequestInit) => request(
      listPath('/api/v1/sites', params), siteCollectionSchema, { ...init, method: 'GET' },
    ),
    getSite: (siteId: string, init?: RequestInit) => request(
      '/api/v1/sites/{siteId}'.replace('{siteId}', encodeURIComponent(siteId)), siteSchema, { ...init, method: 'GET' },
    ),
    listSiteAssets: (siteId: string, params: RegistryListParams = {}, init?: RequestInit) => request(
      listPath('/api/v1/sites/{siteId}/assets'.replace('{siteId}', encodeURIComponent(siteId)), params), assetCollectionSchema, { ...init, method: 'GET' },
    ),
    getAsset: (assetId: string, init?: RequestInit) => request(
      '/api/v1/assets/{assetId}'.replace('{assetId}', encodeURIComponent(assetId)), assetSchema, { ...init, method: 'GET' },
    ),
    listSiteDevices: (siteId: string, params: RegistryListParams = {}, init?: RequestInit) => request(
      listPath('/api/v1/sites/{siteId}/devices'.replace('{siteId}', encodeURIComponent(siteId)), params), deviceCollectionSchema, { ...init, method: 'GET' },
    ),
    listSiteDeviceBindings: (siteId: string, params: RegistryListParams = {}, init?: RequestInit) => request(
      listPath('/api/v1/sites/{siteId}/device-bindings'.replace('{siteId}', encodeURIComponent(siteId)), params), deviceBindingCollectionSchema, { ...init, method: 'GET' },
    ),
    getSiteAssetModel: (siteId: string, init?: RequestInit) => request(
      '/api/v1/sites/{siteId}/asset-model'.replace('{siteId}', encodeURIComponent(siteId)), siteAssetModelSchema, { ...init, method: 'GET' },
    ),
    getSiteDashboardSummary: (siteId: string, init?: RequestInit) => request(
      '/api/v1/sites/{siteId}/dashboard-summary'.replace('{siteId}', encodeURIComponent(siteId)), siteDashboardSummarySchema, { ...init, method: 'GET' },
    ),
    getDevice: (deviceId: string, init?: RequestInit) => request(
      '/api/v1/devices/{deviceId}'.replace('{deviceId}', encodeURIComponent(deviceId)), deviceSchema, { ...init, method: 'GET' },
    ),
    listSiteSpaceChildren: (siteId: string, parentSpaceId: string | null, params: RegistryListParams = {}, init?: RequestInit) => {
      const path = '/api/v1/sites/{siteId}/spaces/tree'.replace('{siteId}', encodeURIComponent(siteId));
      const query = new URLSearchParams();
      if (parentSpaceId) query.set('parentSpaceId', parentSpaceId);
      if (params.limit !== undefined) query.set('limit', String(params.limit));
      if (params.cursor) query.set('cursor', params.cursor);
      return request(`${path}${query.size ? `?${query.toString()}` : ''}`, spaceCollectionSchema, { ...init, method: 'GET' });
    },
    listDevicePoints: (deviceId: string, params: RegistryListParams = {}, init?: RequestInit) => request(
      listPath('/api/v1/devices/{deviceId}/points'.replace('{deviceId}', encodeURIComponent(deviceId)), params), telemetryPointCollectionSchema, { ...init, method: 'GET' },
    ),
    createSite: (body: SiteMutation, init?: RequestInit) => mutation('/api/v1/sites', 'POST', body, siteMutationSchema, siteSchema, init),
    updateSite: (siteId: string, body: SiteMutation, init?: RequestInit) => mutation(
      '/api/v1/sites/{siteId}'.replace('{siteId}', encodeURIComponent(siteId)), 'PATCH', body, siteMutationSchema, siteSchema, init,
    ),
    createSiteSpace: (siteId: string, body: SpaceMutation, init?: RequestInit) => mutation(
      '/api/v1/sites/{siteId}/spaces'.replace('{siteId}', encodeURIComponent(siteId)), 'POST', body, spaceMutationSchema, spaceSchema, init,
    ),
    updateSiteSpace: (siteId: string, spaceId: string, body: SpaceMutation, init?: RequestInit) => mutation(
      '/api/v1/sites/{siteId}/spaces/{spaceId}'.replace('{siteId}', encodeURIComponent(siteId)).replace('{spaceId}', encodeURIComponent(spaceId)), 'PATCH', body, spaceMutationSchema, spaceSchema, init,
    ),
    createSiteAsset: (siteId: string, body: AssetMutation, init?: RequestInit) => mutation(
      '/api/v1/sites/{siteId}/assets'.replace('{siteId}', encodeURIComponent(siteId)), 'POST', body, assetMutationSchema, assetSchema, init,
    ),
    updateSiteAsset: (siteId: string, assetId: string, body: AssetMutation, init?: RequestInit) => mutation(
      '/api/v1/sites/{siteId}/assets/{assetId}'.replace('{siteId}', encodeURIComponent(siteId)).replace('{assetId}', encodeURIComponent(assetId)), 'PATCH', body, assetMutationSchema, assetSchema, init,
    ),
    createSiteDevice: (siteId: string, body: DeviceMutation, init?: RequestInit) => mutation(
      '/api/v1/sites/{siteId}/devices'.replace('{siteId}', encodeURIComponent(siteId)), 'POST', body, deviceMutationSchema, deviceSchema, init,
    ),
    updateSiteDevice: (siteId: string, deviceId: string, body: DeviceMutation, init?: RequestInit) => mutation(
      '/api/v1/sites/{siteId}/devices/{deviceId}'.replace('{siteId}', encodeURIComponent(siteId)).replace('{deviceId}', encodeURIComponent(deviceId)), 'PATCH', body, deviceMutationSchema, deviceSchema, init,
    ),
    createSiteSensor: (siteId: string, body: SensorMutation, init?: RequestInit) => mutation(
      '/api/v1/sites/{siteId}/sensors'.replace('{siteId}', encodeURIComponent(siteId)), 'POST', body, sensorMutationSchema, sensorSchema, init,
    ),
    updateSiteSensor: (siteId: string, sensorId: string, body: SensorMutation, init?: RequestInit) => mutation(
      '/api/v1/sites/{siteId}/sensors/{sensorId}'.replace('{siteId}', encodeURIComponent(siteId)).replace('{sensorId}', encodeURIComponent(sensorId)), 'PATCH', body, sensorMutationSchema, sensorSchema, init,
    ),
    createSitePoint: (siteId: string, body: PointMutation, init?: RequestInit) => mutation(
      '/api/v1/sites/{siteId}/points'.replace('{siteId}', encodeURIComponent(siteId)), 'POST', body, pointMutationSchema, telemetryPointSchema, init,
    ),
    updateSitePoint: (siteId: string, pointId: string, body: PointMutation, init?: RequestInit) => mutation(
      '/api/v1/sites/{siteId}/points/{pointId}'.replace('{siteId}', encodeURIComponent(siteId)).replace('{pointId}', encodeURIComponent(pointId)), 'PATCH', body, pointMutationSchema, telemetryPointSchema, init,
    ),
    rebindRegistryResource: (siteId: string, body: RebindRequest, init?: RequestInit) => mutation(
      '/api/v1/sites/{siteId}/bindings/rebind'.replace('{siteId}', encodeURIComponent(siteId)), 'POST', body, rebindRequestSchema, bindingMutationResultSchema, init,
    ),
    releaseRegistryTemplateRevision: (body: ReleaseTemplateRequest, init?: RequestInit) => mutation(
      '/api/v1/templates/revisions', 'POST', body, releaseTemplateRequestSchema, templateRevisionSchema, init,
    ),
    assignRegistryTemplateRevision: (body: AssignTemplateRequest, init?: RequestInit) => mutation(
      '/api/v1/templates/assignments', 'POST', body, assignTemplateRequestSchema, templateAssignmentSchema, init,
    ),
    planRegistryImport: (siteId: string, body: ImportPlanRequest, init?: RequestInit) => mutation(
      '/api/v1/sites/{siteId}/imports/dry-run'.replace('{siteId}', encodeURIComponent(siteId)), 'POST', body, importPlanRequestSchema, importPlanSchema, init,
    ),
    commitRegistryImport: (siteId: string, body: ImportCommitRequest, init?: RequestInit) => mutation(
      '/api/v1/sites/{siteId}/imports/commit'.replace('{siteId}', encodeURIComponent(siteId)), 'POST', body, importCommitRequestSchema, importCommitResultSchema, init,
    ),
    beginRegistryRetirement: (siteId: string, body: RetireRequest, init?: RequestInit) => mutation(
      '/api/v1/sites/{siteId}/retire'.replace('{siteId}', encodeURIComponent(siteId)), 'POST', body, retireRequestSchema, retirementResultSchema, init,
    ),
    getRuleCatalog: (init?: RequestInit) => request('/api/v1/rules/catalog', ruleCatalogSchema, { ...init, method: 'GET' }),
    listRuleRevisions: (ruleId?: string, init?: RequestInit) => {
      const query = new URLSearchParams();
      if (ruleId) query.set('ruleId', ruleId);
      return request(`/api/v1/rules/revisions${query.size ? `?${query.toString()}` : ''}`, ruleRevisionCollectionSchema, { ...init, method: 'GET' });
    },
    validateRuleDraft: (body: RuleDraft, init?: RequestInit) => mutation('/api/v1/rules/validate', 'POST', body, ruleDraftSchema, ruleValidationResultSchema, init),
    simulateRuleDraft: (body: RuleSimulationRequest, init?: RequestInit) => mutation('/api/v1/rules/simulate', 'POST', body, ruleSimulationRequestSchema, ruleSimulationResultSchema, init),
    releaseRuleRevision: (body: RuleDraft, init?: RequestInit) => mutation('/api/v1/rules/releases', 'POST', body, ruleDraftSchema, ruleRevisionSchema, init),
    listRuleBindings: (siteId: string, init?: RequestInit) => {
      const query = new URLSearchParams({ siteId });
      return request(`/api/v1/rules/bindings?${query.toString()}`, ruleBindingCollectionSchema, { ...init, method: 'GET' });
    },
    assignRuleRevision: (body: RuleAssignmentRequest, init?: RequestInit) => mutation('/api/v1/rules/assignments', 'POST', body, ruleAssignmentRequestSchema, ruleBindingSchema, init),
    retireRuleBinding: (bindingId: string, body: RuleRetirementRequest, init?: RequestInit) => mutation(
      '/api/v1/rules/bindings/{bindingId}/retire'.replace('{bindingId}', encodeURIComponent(bindingId)), 'POST', body, ruleRetirementRequestSchema, ruleBindingSchema, init,
    ),
    listRuleExecutionEvidence: (params: { siteId: string; limit?: number }, init?: RequestInit) => {
      const query = new URLSearchParams({ siteId: params.siteId });
      if (params.limit !== undefined) query.set('limit', String(params.limit));
      return request(`/api/v1/rules/executions?${query.toString()}`, ruleExecutionEvidenceCollectionSchema, { ...init, method: 'GET' });
    },
  };
}
